//
//  SupplementData.swift
//  Riverhead NY Budget App
//
//  Loads the bundled Budget Supplement datasets (generated by the shared ETL,
//  etl/parse_budget_supplement.py) from the app bundle:
//   • reductions.json          — itemized, confidence-tagged 2027 reduction
//                                candidates (controllable lines over their run-rate)
//   • supplement-outliers.json — data-driven budget-accuracy outliers
//   • supplement-lines.json    — the full classified per-account ledger
//
//  These are the single source of truth shared across the iOS, web, and Android
//  apps; nothing here re-derives or hard-codes the figures.
//

import Foundation

// MARK: - Reductions

struct SupplementReduction: Identifiable, Decodable, Hashable {
    let account: String
    let name: String
    let fund: String
    let fundName: String
    let actual2024: Double?
    let ytd2025: Double?
    let tentative2026: Double?
    let target: Double
    let confidence: String   // "firm" | "moderate" | "volatile"

    var id: String { account }
}

struct SupplementReductionsFile: Decodable {
    let gapToClose: Double
    let total: Double
    let byConfidence: [String: Double]
    let items: [SupplementReduction]
    let method: String
}

// MARK: - Outliers

struct SupplementOutlier: Identifiable, Decodable, Hashable {
    let account: String
    let fund: String
    let name: String
    let control: String
    let actual2024: Double?
    let budget2025: Double?
    let ytd2025: Double?
    let tentative2026: Double?
    let flag: String
    let excess: Double

    var id: String { "\(flag)-\(account)" }
}

struct SupplementOutliersFile: Decodable {
    let overBudget: [SupplementOutlier]
    let chronicOverrun: [SupplementOutlier]
    let noBudget: [SupplementOutlier]
    let recoverablePoolControllable: Double
    let note: String
}

// MARK: - Line items

struct SupplementLine: Identifiable, Decodable, Hashable {
    let account: String
    let fund: String
    let name: String
    let kind: String       // "expenditure" | "revenue"
    let control: String    // "mandated" | "personnel" | "controllable" | "revenue"
    let actual2024: Double?
    let budget2025: Double?
    let ytd2025: Double?
    let request2026: Double?
    let tentative2026: Double?
    let actual2023: Double?
    let budget2024: Double?
    let ytd2024: Double?
    let tentative2025: Double?
    let overBudget2026: Double?

    var id: String { account }
}

private struct SupplementLinesFile: Decodable { let lines: [SupplementLine] }

// MARK: - Multi-year history (2020-2026 supplements)

// Each supplement prints an actual from two years back, so stacking seven of
// them gives an unbroken 2018-2024 actual on the same account. That span is
// what separates a line genuinely over budget from one that simply runs on a
// multi-year cycle and happens to be in an off year.

struct SupplementCyclicalLine: Identifiable, Decodable {
    let account: String
    let name: String
    let series: [String: Double]
    let spikeYears: [Int]
    let periodYears: Int
    let nextDue: Int
    let spikeAverage: Double
    let adopted2025: Double
    let tentative2026: Double

    var id: String { account }
}

struct SupplementUnderBudgetedLine: Identifiable, Decodable {
    let account: String
    let name: String
    let series: [String: Double]
    let quietYears: Int
    let averageWhenActive: Double
    let peak: Double
    let adopted2025: Double
    let tentative2026: Double
    let shortfall: Double

    var id: String { account }
}

struct SupplementRenumberedLine: Identifiable, Decodable {
    let name: String
    let oldAccount: String
    let lastYear: Int
    let newAccount: String
    let firstYear: Int
    let peak: Double

    var id: String { oldAccount }
}

struct SupplementHistoryFile: Decodable {
    let actualYears: [Int]
    let accountsTracked: Int
    let cyclical: [SupplementCyclicalLine]
    let dueIn2027: [SupplementCyclicalLine]
    let underBudgeted: [SupplementUnderBudgetedLine]
    let renumbered: [SupplementRenumberedLine]
    let note: String
}

// MARK: - The newest Supplement's lines (2027)
// budget-supplement/current-lines.json on the website: one Supplement's columns named
// by role, with `columns` giving each role's year (actual 2025, adopted 2026, ytd 2026,
// request/tentative/preliminary 2027, priorActual 2024, priorAdopted 2025, priorYtd 2025).

struct SupplementCurrentLine: Identifiable, Decodable, Hashable {
    let account: String
    let fund: String
    let name: String
    let kind: String
    let control: String
    let page: Int?
    let priorActual: Double?
    let actual: Double?
    let priorAdopted: Double?
    let adopted: Double?
    let priorYtd: Double?
    let ytd: Double?
    let request: Double?
    let tentative: Double?
    let preliminary: Double?

    var id: String { account }

    /// The newest stage's figure: the Preliminary when printed, else the Tentative.
    var proposal: Double? { preliminary ?? tentative }

    /// The trailing full-year run-rate: the larger of last year's actual and twice this
    /// year's year-to-date, as etl/parse_supplement_history.py computes it.
    var runRate: Double? {
        guard actual != nil || ytd != nil else { return nil }
        return max(actual ?? 0, (ytd ?? 0) * 2)
    }

    /// How far the newest stage sits above (+) or below (−) the run-rate.
    var overRunRate: Double? {
        guard let proposal, let runRate else { return nil }
        return proposal - runRate
    }
}

struct SupplementCurrentFile: Decodable {
    let supplementYear: Int
    let columns: [String: Int]
    let lines: [SupplementCurrentLine]
}

// MARK: - Loader

enum SupplementData {
    static let reductions: SupplementReductionsFile? = load("reductions")
    static let outliers: SupplementOutliersFile? = load("supplement-outliers")
    static let lines: [SupplementLine] = (load("supplement-lines") as SupplementLinesFile?)?.lines ?? []
    static let history: SupplementHistoryFile? = load("supplement-history")
    static let currentLines: SupplementCurrentFile? = load("supplement-current-lines")

    private static func load<T: Decodable>(_ resource: String) -> T? {
        guard let url = Bundle.main.url(forResource: resource, withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(T.self, from: data)
    }
}
